"use strict";

angular
	.module("irtech.netcity.em.talents")
	.controller("ListStudentAwardsCtrl", ($scope, $http, $routeParams, $location, $appLoader, $uibModal, $controller, settingsProvider, pageContext) => {

		pageContext.title = "Личные достижения";
		pageContext.back = { history: true };
		pageContext.parent = {
				title: language.Generic.MenuFolders.kFNTalentStudents,
				href: `students`
		};

		$scope.viewEvent = (eventId) => {
			window.postTo(`/angular/em/events/${eventId}/members`, { backUrl: "/angular/em/talents/students/" + $routeParams.studentId + "/awards" });
		};

		//наследование от базового контроллера
		$controller("ListStudentAwardsCmnCtrl", { $scope, $http, $routeParams, $location, $appLoader });
	});


