"use strict";

import SearchSource from "./../../../../global/searchSource.js";


angular
	.module("irtech.netcity.em.talents")
	.controller("AddCuratorCtrl",
		($scope, $http, $alerts, $uibModalInstance, schoolId) => {
			$scope.header = "Назначение куратора";

			$.extend($scope,
			{
				language: language,
				data: {
					curator: {
						schoolId: null,
						userId: null
					}
				}
			});

			$scope.searchCtx = new SearchSource({
				schools: {
					url: "/webapi/schools/search",
					searchParam: "name",
					params: { take: 20 }
				},
				staffs: {
					url: () => "/webapi/users/search",
					searchParam: "name",
					params: {
						staff: true,
						take: 20,
						potentialCurator: true,
						schoolId: () => $scope.data.curator.schoolId
					}
				}
			}, $http);

			$scope.save = () => {

				$http.put(`/webapi/talents/curators/`, $scope.data.curator)
					.then(() => {
						$uibModalInstance.close($scope.data.curator);
						$alerts.success(language.Generic.TalentStudents.kOrgStaffAssignedCurator);
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});

			};

			$scope.cancel = () => {
				$uibModalInstance.dismiss("cancel");
			}
		});


