//angular = require 'angular'

const module = angular.module("irtech.netcity.em.talents",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components",
		"irtech.netcity.directive", 
		"irtech.netcity.school.portfolio.common", "irtech.netcity.em.events.common", "irtech.netcity.em.talents.common"
	]);

const registryTemplate = "/static/dist/app/global/templates/registryAs.html";

import { TalentsStudentsRegistryController } from "./students/registry/talentsStudentsRegistryCtrl";
import { AchievementsRegistryController } from "./achievements/registry/achievementsRegistryCtrl";

require("./students/list/listStudentsCtrl.js");
require("./students/assignCurator/assignCuratorCtrl.js");
require("./students/portfolio/viewStudentPortfolioCtrl.js");
require("./students/awards/listStudentAwardsCtrl.js");

require("./curators/list/listCuratorsCtrl.js");
require("./curators/add/addCuratorCtrl.js");

require("./common/students/awards/listStudentAwardsCmnCtrl.js");
require("./common/students/portfolio/viewStudentPortfolioCmnCtrl.js");

require("approot/school/portfolio/common/view/portfolioDir.js");

require("approot/global/directives/storageDirective.coffee");

module
	.controller("TalentsStudentsRegistryController", TalentsStudentsRegistryController)
	.controller("AchievementsRegistryController", AchievementsRegistryController)
	.filter("extension", () => {
		return (input) => {
			return input.split(".").pop();
		}
	})
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/students", {
				reloadOnSearch: false,
				templateUrl: registryTemplate,
				controller: "TalentsStudentsRegistryController as ctrl"
			})
			//.when("/students", {
			//	templateUrl: "/static/dist/app/em/talents/students/list/template.html",
			//	controller: "ListStudentsCtrl"
			//})
			.when("/students/:studentId/portfolio", {
				templateUrl: "/static/dist/app/em/talents/common/students/portfolio/template.html",
				controller: "ViewStudentPortfolioCtrl"
			})
			.when("/students/:studentId/awards", {
				templateUrl: "/static/dist/app/em/talents/common/students/awards/template.html",
				controller: "ListStudentAwardsCtrl"
			})
			.when("/curators", {
				templateUrl: "/static/dist/app/em/talents/curators/list/template.html",
				controller: "ListCuratorsCtrl"
			})
			.when("/achievements", {
				templateUrl: "/static/dist/app/global/templates/registryAs.html",
				controller: "AchievementsRegistryController as ctrl"
			})
			.otherwise({
				redirectTo: "/students"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



