angular
	.module("irtech.netcity.school.portfolio.common", [])
	.directive("portfolioGroupLinks", ($compile) => {
		return {
			restrict: "A",
			scope: {
				links: "=links",
				end: "=end"
			},
			replace: true,
			template: `<li class="tree-group-item">
						<span ng-class="{'border-remove': end}">
							<label>Ссылки</label>
						</span>
						<div>
							<a ng-repeat-start="link in links" href="{{link.url}}" target="_blank">{{link.url}}</a><p ng-repeat-end>{{link.description}}</p>
						</div>
					</li>`
		}
	})
	.directive("portfolioGroupDocs", ($compile) => {
		return {
			restrict: "A",
			scope: {
				docs: "=docs",
				end: "=end",
				opendoc: "=opendoc"
			},
			replace: true,
			template: `<li class="tree-group-item">
						<span ng-class="{'border-remove': end}">
							<label>Документы</label>
						</span>
						<div>
							<dl ng-repeat="doc in docs" class="doc-item">
								<dt><span class ="doc-type" fileExt="{{doc.fileName | extension}}"><span class ="fileCorner"></span></dt>
								<dd class="doc-data">
									<a class ="mdi mdi-file" href="#" ng-click="opendoc(doc.downloadUrl, doc.name)">
										<span class ="name_file">{{doc.name}}</span>
									</a>
									<p class ="doc-descr">{{doc.description}}</p>
								</dd>
							</dl>
						</div>
					</li>`
		}
	})
	.directive("portfolioSubgroup", ($compile) => {
		const template = `
			<li class ="tree-group-item tree-group-subgroup">
				<span>
					<label for="{{group.id}}" class ="section-level">{{group.name}}</label>
					<a ng-href="{{editurl}}?groupId={{group.id}}" ng-if="!readonly" title="Редактировать" class="primary edit-group-link"
						style="float: right; position: relative;top: -10px;left: -10px;color: white;outline: none !important;">
						<span class ="glyphicon glyphicon-pencil" style="border: 0;">
						</span>
					</a>
				</span>
				<div>
					<input type="checkbox" checked id="{{group.id}}">
					<ul class="tree-group-item">
						<li portfolio-group-links links="group.links" end="group.groups.length == 0" ng-if="group.links.length > 0"></li>
						<li portfolio-group-docs docs="group.docs" end="group.groups.length == 0" ng-if="group.docs.length > 0" opendoc="opendoc"></li>

						<li portfolio-subgroup group="subgroup" editurl="editurl" opendoc="opendoc" readonly="readonly" ng-repeat="subgroup in group.groups" ng-if="group.groups.length > 0"></li>
					</ul>
				</div>
			</li>`;

		return {
			restrict: "A",
			scope: {
				editurl: "=editurl",
				readonly: "=readonly",
				group: "=group",
				opendoc: "=opendoc"
			},
			template: template,
			replace: true
		}
	})
	.directive("portfolioGroup", ($compile) => {
		const template = `
			<li class ="tree-group">
				<span>
					<label for="{{group.id}}">{{group.name}}</label>
					<a ng-href="{{editurl}}?groupId={{group.id}}" ng-if="!readonly" title="Редактировать" class="primary edit-group-link"
						style="float: right; position: relative;top: -10px;left: -10px;color: white;outline: none !important;">
						<span class ="glyphicon glyphicon-pencil" style="border: 0;">
						</span>
					</a>
				</span>
				<input type="checkbox" checked id="{{group.id}}">
				<ul class="tree-group-item">
					<li portfolio-group-links links="group.links" ng-if="group.links.length > 0"></li>
					<li portfolio-group-docs docs="group.docs" opendoc="opendoc" end="group.groups.length == 0" ng-if="group.docs.length > 0"></li>

					<li portfolio-subgroup group="subgroup" editurl="editurl" readonly="readonly" opendoc="opendoc" ng-repeat="subgroup in group.groups" ng-if="group.groups.length > 0"></li>
				</ul>
			</li>`;

		return {
			restrict: "A",
			scope: {
				editurl: "=editurl",
				readonly: "=readonly",
				group: "=group",
				opendoc: "=opendoc"
			},
			template: template,
			replace: true
		}
	})


