"use strict";

angular
	.module("irtech.netcity.em.talents")
	.controller("AssignStudentCuratorCtrl",
		($scope, $http, $alerts, $uibModalInstance, student) => {
			$scope.header = language.Generic.TalentStudents.kCuratorToStudentAssign;

			$.extend($scope,
			{
				language: language,
				data: {
					student: student,
					curators: [],
					curator: student.curators[0]
				},
				state: {
					edit: student.curators.length > 0, 
					ready: false
				}
			});

			const defaultErrHandler = (response) => $alerts.error(response.data.message, response.data.details);

			$http.get(`/webapi/talents/curators`)
				.then((response) => {
					$scope.data.curators = response.data;
					$scope.state.ready = true;
				})
				.catch(defaultErrHandler);


			$scope.remove = () => {
				$http.delete(`/webapi/talents/students/${$scope.data.student.id}/curators/`, { params: { curatorId: $scope.data.curator.userId } })
					.then(() => {
						$alerts.success(language.Generic.TalentStudents.kCuratorToStudentSuccesAssigned);
						$uibModalInstance.close();
					})
					.catch(defaultErrHandler);

			};

			$scope.save = () => {
				$http.put(`/webapi/talents/students/${$scope.data.student.id}/curators/`, null, { params: { curatorId: $scope.data.curator.userId } })
					.then(() => {
						$alerts.success(language.Generic.TalentStudents.kCuratorToStudentSuccesAssigned);
						$uibModalInstance.close($scope.data.curator);
					})
					.catch(defaultErrHandler);
			};

			$scope.cancel = () => $uibModalInstance.dismiss("cancel");
		});


