declare var dateUtils: any;

import { RegistryController, RegistryInfo, RegistryBtn, SelectionMode } from "approot/global/controllers/registryAsCtrl";
import { AppLoader } from "approot/global/apploader";
import { PageContext } from "approot/global/services/context";

export class TalentsStudentsRegistryController extends RegistryController {

	/*@ngInject*/
	constructor($injector, pageContext: PageContext, $scope: any, language: any, $appLoader: AppLoader, $dialogs: any, $uibModal: any, $alerts: any, $location: any) {
		pageContext.title = language.Generic.MenuFolders.kFNTalentStudents;
		pageContext.back = null;
		pageContext.parent = null;

		const viewPortfolioButton: RegistryBtn = {
			title: "Портфолио",
			action: () => {
				this.viewPortfolio();
			},
			selectionMode: SelectionMode.Single,
			icon: "glyphicon glyphicon-briefcase",
			style: "btn-info"
		};

		const viewAwardsButton: RegistryBtn = {
			title: "Личные достижения",
			action: () => {
				this.viewAwards();
			},
			selectionMode: SelectionMode.Single,
			icon: "glyphicon glyphicon-education",
			style: "btn-warning"
		};

		const assignCuratorButton: RegistryBtn = {
			title: language.Generic.TalentStudents.kAssignCurator,
			action: () => {
				this.assignCurator();
			},
			selectionMode: SelectionMode.Single,
			icon: "icon-group",
			style: "btn-warning"
		};

		const dateDecorator = { type: "map", map: date => dateUtils.date2str(new Date(date)) };

		const registry: RegistryInfo = {
			url: "/webapi/em/talents/registry",
			filtersUrl: "/webapi/em/talents/registry/filter",
			fieldDecorators: {
				"birthDate": dateDecorator
			},
			buttons: [viewPortfolioButton, viewAwardsButton, assignCuratorButton],
			linkButtons: [],
			extensions: null,
			compactFilters: true
		};

		if ($location.search() && $location.search().curatorId) {
			registry.filtersValues = { "CuratorFilter": $location.search().curatorId };
		}
		// сразу очистка
		$location.search({});

		super($injector, $scope, $appLoader, $dialogs, $uibModal, $alerts, language, registry);

		this.$location = $location;
	}

	$location: any;

	// просмотр портфолио
	viewPortfolio(): void {
		let studentId = this.selection.selected[0].id;
		this.$location.path(`/students/${studentId}/portfolio`);
	}

	// просмотр личных достижений
	viewAwards(): void {
		let studentId = this.selection.selected[0].id;
		this.$location.path(`/students/${studentId}/awards`);
	}

	// назначение куратора
	assignCurator(): void {
		let selected = this.selection.selected[0];

		this.$http.get(`/webapi/talents/student`, { params: { studentId: selected.id } }).then((response) => {
			const modalInstance = this.$uibModal.open({
				templateUrl: "/static/dist/app/em/talents/students/assignCurator/template.html",
				controller: "AssignStudentCuratorCtrl",
				size: "md",
				resolve: {
					student: () => response.data
				}
			});

			modalInstance.result.then(() => {
				this.load();
			});
		});
	}
}


