"use strict";

import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.em.talents")
	.controller("ListStudentsCtrl", ($scope, $http, $q, $alerts, $dialogs, $appLoader, $routeParams, $uibModal, $location) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kFNTalentStudents
		}

		$.extend($scope, {
			language: language,
			filter: {
				items: {
					curators: [],
					schools: []
				},
				selected: {
					curator: null,
					school: null
				}
			},
			data: {
				selected: null,
				students: [],
				viewStudents: []
			},
			paging: {
				page: 1,
				pageSize: 20,
				totalcount: 0
			},
			state: {
				dataReady: false
			}
		});

		const kClass = $scope.language.Common.kClass;
		$scope.language.Common.kClass = kClass[0].toUpperCase() + kClass.substring(1);

		if ($routeParams.curatorId) {
			$scope.filter.selected.curator = { userId: $routeParams.curatorId };
		}

		const mapStudents = (studentsDto) => {
			const schoolsIdx = _.indexBy($scope.filter.items.schools, "id");
			const curatorsIdx = _.indexBy($scope.filter.items.curators, "userId");

			// Отложенный маппинг
			const getUserInfo = (student, userId) => {
				$http.get('/webapi/users/get', { params: {userId:userId} } )
				.then((response) => {
					const user = response.data;
					const curator = {
						userId: user.id,
						fio: user.name
					}
					// Ищем и заменяем неизвестные id куратора на id и ФИО
					student.curators = _.map(student.curators, (o) => o === userId ? curator : o);
				});
				// Возвращаем id пользователя, чтобы можно было отыскать куда вставлять данные
				return userId;
			}

			return _.map(studentsDto,
				(studentDto) => {
					if (studentDto.education && studentDto.education.schoolId > 0) {
						studentDto.education.school = schoolsIdx[studentDto.education.schoolId];
					}
					if (studentDto.curators && studentDto.curators.length) {
						studentDto.curators = _.map(studentDto.curators, (curatorId) => curatorsIdx[curatorId] || getUserInfo(studentDto, curatorId));
					}
					studentDto.birthDate = dateUtils.date2str(new Date(studentDto.birthDate));
					return studentDto;
				});
		}

		const loadCurators = $http.get(`/webapi/talents/curators`)
			.then((response) => {
				$scope.filter.items.curators = response.data;
				$scope.filter.items.curators.unshift({ userId: -1, fio: "Все" });
				if ($routeParams.curatorId) {
					$scope.filter.selected.curator = _.findWhere($scope.filter.items.curators, {userId: $routeParams.curatorId});
				}
				$scope.filter.selected.curator = $scope.filter.selected.curator || $scope.filter.items.curators[0];
			});

		const loadSchools = $http.get(`/webapi/talents/schools`)
			.then((response) => {
				$scope.filter.items.schools = response.data;
				$scope.filter.items.schools.unshift({ id: -1, name: "Все" });
				$scope.filter.selected.school = $scope.filter.items.schools[0];
			});

		const loadStudents = () => {
			const params = {
				page: $scope.paging.page,
				pageSize: $scope.paging.pageSize,
			};

			if ($scope.filter.selected.school && $scope.filter.selected.school.id > 0) {
				params.schoolId = $scope.filter.selected.school.id;
			}
			if ($scope.filter.selected.curator && $scope.filter.selected.curator.userId > 0) {
				params.curatorId = $scope.filter.selected.curator.userId;
			}

			return $http.get(`/webapi/talents/students`, { params })
				.then((response) => {
					$scope.data.students = response.data;
					$scope.paging.totalcount = parseInt(response.headers("count"));
					$scope.paging.show = $scope.paging.totalcount > $scope.paging.pageSize;
				});
		};

		$scope.load = () => {
			$scope.state.dataReady = false;
			$scope.data.selection.dropSelect();

			$q.all([loadCurators, loadSchools, loadStudents()])
				.then(() => {
					$scope.data.students = mapStudents($scope.data.students);
					//$scope.filterViewStudents();
					$scope.data.viewStudents = $scope.data.students;
					$appLoader.hide();
					$scope.state.dataReady = true;
				});
		};

		$scope.onFilterChange = () => {
			$scope.state.dataReady = false;

			$scope.paging.page = 1;
			loadStudents().then(() => {
				$scope.data.students = mapStudents($scope.data.students);
				//$scope.filterViewStudents();
				$scope.data.viewStudents = $scope.data.students;
				$appLoader.hide();
				$scope.state.dataReady = true;
			});
		}

		$scope.data.selection = new Selectable();
		
		//просмотр личных достижений
		$scope.viewAwards = () => {
			$location.path(`/students/${$scope.data.selection.selected.id}/awards`);
		}

		//просмотр портфолио
		$scope.viewPortfolio = () => {
			$location.path(`/students/${$scope.data.selection.selected.id}/portfolio`);
		}

		//назначение куратора
		$scope.assignCurator = () => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/em/talents/students/assignCurator/template.html",
				controller: "AssignStudentCuratorCtrl",
				size: "md",
				resolve: {
					student: () => $scope.data.selection.selected
				}
			});
			modalInstance.result.then($scope.load, () => document.activeElement.blur() );
			// Сбиваем фокус с активного элемента	^ #21205
		}

		$scope.load();
	});



