"use strict";

import Selectable from "approot/global/selectable";

angular
	.module("irtech.netcity.em.talents")
	.controller("ListCuratorsCtrl", ($scope, $http, $q, $alerts, $dialogs, $appLoader, $location, $uibModal, settingsProvider, pageContext) => {
		pageContext.title = language.Generic.MenuFolders.kFEOCurators;
		pageContext.parent = null;
		 
		$.extend($scope, {
			language: language,
			filter: {
				items: {
					schools: []
				},
				selected: {
					school: {id: -1, name: "Все"}
				}
			},
			data: {
				selected: null,
				curators: [],
				viewCurators: []
			},
			state: {
				dataReady: false
			}
		});

		$scope.data.selection = new Selectable();

		$scope.load = () => {
			$http.get(`/webapi/talents/curators`)
			.then((response) => {

				$scope.data.curators = response.data;
				$scope.filterViewCurators();

				const schoolIds = _.pluck($scope.data.curators, "schoolId");
				if (schoolIds.length) {
					return $http.post(`/webapi/schools/short`, schoolIds, { params: { withCityName: true } });
				} else {
					return { data: [] };
				}
			})
			.then((response) => {

				$scope.filter.items.schools = response.data;
				$scope.filter.items.schools.unshift({id: -1, name: "Все"});

				const schoolsIdx = _.indexBy(response.data, "id");
				_.each($scope.data.curators, (curator) => {
					curator.school = schoolsIdx[curator.schoolId];
				});

				$appLoader.hide();
				$scope.state.dataReady = true;

			});

		}
		
		$scope.filterViewCurators = () => {
			$scope.data.viewCurators = _.filter($scope.data.curators, (curator) => {
				if ($scope.filter.selected.school.id > 0 && curator.schoolId !== $scope.filter.selected.school.id) {
					return false;
				}
				return true;
			});
		}

		//todo. загрузка списка кураторов
		//todo. фильтрация на клиенте

		$scope.viewStudents = () => {
			$location.path(`/students/`).search({ curatorId: $scope.data.selection.selected.userId });
		}

		//добавление куратора
		$scope.add = () => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/em/talents/curators/add/template.html",
				controller: "AddCuratorCtrl",
				size: "md",
				resolve: {
					schoolId: () => $scope.filter.selected.school.id
				}
			});

			modalInstance.result.then(() => {$scope.load();});
		}

		//удаление куратора
		$scope.delete = () => {
			$dialogs.confirm("Вы действительно желаете удалить куратора?")
				.then(() => $http.delete(`/webapi/talents/curators`, { params: { id: $scope.data.selection.selected.userId } }).catch((response) => $alerts.error(response.data.message, response.data.details)))
				.then(() => {
					$alerts.success("Куратор успешно удален");
					$scope.load();
				});
		}

		$scope.load();
	});



