"use strict";

angular
	.module("irtech.netcity.em.talents")
	.controller("ViewStudentPortfolioCtrl", ($scope, $http, $routeParams, $location, $appLoader, pageContext, $controller) => {

		pageContext.title = "Просмотр портфолио";
		pageContext.back = { history: true };
		pageContext.parent = {
			title: language.Generic.MenuFolders.kFNTalentStudents,
			href: `students`
		};

		angular.extend($scope, {
			language: language,
			editurl: "",
			data: {
				studentId: $routeParams.studentId,
				portfolio: null
			},
			state: {
				emptyData: false,
				readonly: true
			}
		});

		$http.get(`/webapi/portfolios/personal/`, { params: { userId: $scope.data.studentId} })
			.then((response) => {
				$scope.data.portfolio = response.data;
				if ($scope.data.portfolio == null) {
					$scope.state.emptyData = true;
				}
				$appLoader.hide();
			});

		$controller("ViewStudentPortfolioCmnCtrl", { $scope, $http, $routeParams, $location, $appLoader });
	});



